import sys; sys.path.insert(0,'/home/claude/dco/_pipeline/tools')
from ext import *
ext('c10_eng_ch5',[
C("🕊️","नोबेल शांति पुरस्कार क्या है",["नोबेल पुरस्कार स्वीडिश वैज्ञानिक के नाम पर","शांति पुरस्कार नॉर्वे के ओस्लो में","शांति के लिए काम करने वालों को","हर साल दिसंबर में समारोह"],"इस पाठ को समझने के लिए पहले नोबेल शांति पुरस्कार को जानिए। यह पुरस्कार स्वीडन के वैज्ञानिक अल्फ़्रेड नोबेल की वसीयत से शुरू हुआ। बाक़ी नोबेल पुरस्कार स्वीडन में दिए जाते हैं, पर शांति पुरस्कार नॉर्वे की राजधानी ओस्लो में दिया जाता है। यह उन लोगों या संस्थाओं को मिलता है जिन्होंने दुनिया में शांति, भाईचारे और मानवाधिकार के लिए बड़ा काम किया हो। हर साल दिसंबर में समारोह होता है, जहाँ विजेता या उनके प्रतिनिधि भाषण देते हैं। हमारे भारत से मदर टेरेसा, कैलाश सत्यार्थी और अन्य लोगों को भी यह सम्मान मिला है।"),
C("🎤","बेटे का भाषण",["माँ की जगह बेटे ने पुरस्कार लिया","मैं माँ की ओर से बोल रहा हूँ","शब्द अपने, भावना माँ की","पूरी जनता के लिए पुरस्कार"],"इस पाठ की ख़ास बात है कि भाषण सू की के बेटे ने दिया। वे ओस्लो नहीं आ सकती थीं, क्योंकि उस समय वे अपने घर में नज़रबंद थीं। इसलिए उनके बेटे ने मंच पर आकर पुरस्कार स्वीकार किया। उसने कहा कि मैं अपनी माँ की ओर से बोल रहा हूँ, पर अपने शब्दों में। इस भाषण में आप निजी भावना भी पाएँगे और पूरे देश का दुख और उम्मीद भी। बेटे ने साफ़ कहा कि यह पुरस्कार सिर्फ़ उसकी माँ का नहीं, बल्कि बर्मा की पूरी जनता का है, जो लोकतंत्र के लिए संघर्ष कर रही है।"),
C("🏛️","लोकतंत्र का अर्थ",["जनता का, जनता द्वारा, जनता के लिए शासन","चुनाव से सरकार चुनना","बोलने और सोचने की आज़ादी","क़ानून के सामने सब बराबर"],"भाषण का मूल विषय लोकतंत्र है, इसलिए उसे ठीक से समझ लीजिए। लोकतंत्र यानी वह शासन, जिसमें जनता अपने प्रतिनिधियों को चुनती है। अब्राहम लिंकन ने कहा था कि यह जनता का, जनता द्वारा और जनता के लिए शासन है। लोकतंत्र में हर नागरिक को बोलने, सोचने और अपनी राय रखने की आज़ादी होती है। क़ानून के सामने सब बराबर होते हैं। भारत दुनिया का सबसे बड़ा लोकतंत्र है, और हमारे बिहार में भी हर चुनाव में लोग उत्साह से वोट देते हैं। इसलिए हमें अपने लोकतंत्र की क़द्र करनी चाहिए।"),
C("⚖️","मानवाधिकार क्या हैं",["हर इंसान के जन्मसिद्ध अधिकार","जीने और आज़ादी का अधिकार","शिक्षा और न्याय का अधिकार","संयुक्त राष्ट्र की घोषणा"],"भाषण में बार-बार मानवाधिकार की बात आती है। मानवाधिकार वे अधिकार हैं जो हर इंसान को सिर्फ़ इंसान होने के कारण मिलते हैं, चाहे उसका धर्म, जाति, लिंग या देश कुछ भी हो। इनमें जीने का, आज़ादी का, शिक्षा का और न्याय पाने का अधिकार शामिल है। संयुक्त राष्ट्र ने उन्नीस सौ अड़तालीस में मानवाधिकारों की सार्वभौमिक घोषणा अपनाई थी। जब किसी देश में लोगों की आवाज़ दबाई जाती है, तो वहाँ मानवाधिकारों का उल्लंघन होता है। इसीलिए सू की जैसे लोग इन अधिकारों के लिए संघर्ष करते हैं।"),
C("🧘","अहिंसा की शक्ति",["हथियार के बिना संघर्ष","गांधी, मंडेला और सू की","साहस और धैर्य की ज़रूरत","अहिंसा कमज़ोरी नहीं, ताक़त"],"भाषण की दूसरी बड़ी बात अहिंसा है। सू की ने हथियार उठाने के बजाय शांत तरीक़े से अपनी आवाज़ उठाई। गांधी जी ने भारत की आज़ादी के लिए यही रास्ता अपनाया था। दक्षिण अफ़्रीका के नेल्सन मंडेला ने भी लंबे समय तक अन्याय के ख़िलाफ़ शांतिपूर्ण लड़ाई लड़ी। बहुत से लोग सोचते हैं कि अहिंसा कमज़ोरी है, पर असल में इसके लिए बहुत साहस, धैर्य और आत्म-नियंत्रण चाहिए। बिना हथियार के अन्याय के सामने खड़े रहना हिम्मत का काम है। परीक्षा में अहिंसा और गांधी जी से संबंध ज़रूर लिखिए।"),
C("🇮🇳","भारत से संबंध",["सू की ने दिल्ली में पढ़ाई की","माँ भारत में राजदूत थीं","गांधी और नेहरू से प्रेरणा","भारत-म्यांमार पड़ोसी देश"],"सू की का भारत से भी गहरा रिश्ता रहा है। उनकी माँ भारत में म्यांमार की राजदूत थीं, इसलिए सू की ने अपनी किशोरावस्था के कुछ साल दिल्ली में बिताए और यहाँ पढ़ाई की। यहीं उन्होंने गांधी जी और नेहरू के विचारों के बारे में सीखा, जिनका असर उनके जीवन पर बहुत पड़ा। भारत और म्यांमार पड़ोसी देश हैं। बिहार के बोधगया और म्यांमार के बौद्ध श्रद्धालुओं के बीच भी पुराना संबंध है, क्योंकि बुद्ध की ज्ञानभूमि बोधगया हमारे बिहार में है और वहाँ म्यांमार से भी बहुत लोग आते हैं।"),
C("💪","त्याग और साहस",["परिवार से वर्षों की दूरी","अकेले बंद घर में जीवन","फिर भी उम्मीद बनाए रखी","जनता के लिए व्यक्तिगत सुख छोड़ा"],"भाषण में त्याग यानी सैक्रिफ़ाइस की बात भी है। सू की अपने परिवार से कई साल दूर रहीं। उनके बेटे बचपन में माँ से अलग रहे, और माँ के सम्मान समारोह में भी वे अकेले आ सके। फिर भी उन्होंने अपने देश के लोगों के लिए संघर्ष करना नहीं छोड़ा। यह त्याग हमें सिखाता है कि बड़े उद्देश्य के लिए कई बार व्यक्तिगत सुख छोड़ना पड़ता है। हम विद्यार्थी भी जब मोबाइल या खेल से समय निकालकर पढ़ते हैं, तो एक छोटा त्याग ही करते हैं, जो आगे बड़ा फल देता है।"),
C("📝","शब्दार्थ दोहराइए",["एक्सेप्टेंस यानी स्वीकृति","डेमोक्रेसी यानी लोकतंत्र","ह्यूमन राइट्स यानी मानवाधिकार","नॉन वायलेंट और सैक्रिफ़ाइस"],"आइए नए शब्द दोहराएँ। एक्सेप्टेंस यानी स्वीकृति, डेमोक्रेसी यानी लोकतंत्र, ह्यूमन राइट्स यानी मानवाधिकार, नॉन वायलेंट यानी अहिंसक और सैक्रिफ़ाइस यानी त्याग। साथ में पीस यानी शांति, फ्रीडम यानी आज़ादी और करेज यानी साहस भी याद कर लीजिए। अब हर शब्द से एक वाक्य बनाइए। जैसे डेमोक्रेसी गिव्ज़ पावर टू द पीपल, यानी लोकतंत्र जनता को शक्ति देता है। और पीस इज़ मोर पावरफ़ुल दैन वॉर, यानी शांति युद्ध से ज़्यादा शक्तिशाली है। इन वाक्यों को कॉपी में लिखिए।"),
C("🧩","व्याकरण: पैसिव वॉइस",["कर्म प्रधान वाक्य","बी वर्ब के साथ तीसरा रूप","द प्राइज़ वाज़ अवॉर्डेड","कर्ता कभी-कभी छिप जाता है"],"इस भाषण में कर्मवाच्य यानी पैसिव वॉइस के वाक्य बहुत हैं। जब वाक्य में काम करने वाले से ज़्यादा काम महत्वपूर्ण हो, तब पैसिव वॉइस काम आती है। इसे बनाने के लिए बी वर्ब और क्रिया का तीसरा रूप लगता है। जैसे द प्राइज़ वाज़ अवॉर्डेड टू हर, यानी पुरस्कार उन्हें दिया गया। द ऑर्डर वाज़ फ़ॉलोड, यानी आदेश का पालन किया गया। यहाँ करने वाला कौन है, इस पर ज़ोर नहीं है। एक्टिव और पैसिव के पाँच जोड़े वाक्य बनाइए। जैसे एक्टिव, वी रिस्पेक्ट हर। पैसिव, शी इज़ रिस्पेक्टेड बाय अस।"),
C("📢","भाषण लिखने की कला",["शुरुआत में अभिवादन","विषय का परिचय","मुख्य बातें क्रम से","अंत में प्रेरणादायक संदेश"],"यह पाठ एक भाषण है, तो भाषण लिखना भी सीख लीजिए। शुरुआत में सबको संबोधित कीजिए, जैसे रेस्पेक्टेड टीचर्स एंड डियर फ़्रेंड्स। फिर विषय का परिचय दीजिए। इसके बाद मुख्य बातें क्रम से रखिए, हर बात के लिए एक छोटा अनुच्छेद। अंत में एक प्रेरणादायक संदेश दीजिए और धन्यवाद कहिए। अपने स्कूल के वार्षिकोत्सव या स्वतंत्रता दिवस पर आप भी ऐसा भाषण दे सकते हैं। आज एक छोटा भाषण लोकतंत्र पर लिखिए, जो एक मिनट में पूरा पढ़ा जा सके।"),
C("📌","पाठ का सार",["सू की को नोबेल शांति पुरस्कार","नज़रबंदी में होने से बेटे ने भाषण दिया","लोकतंत्र, मानवाधिकार, अहिंसा","पुरस्कार पूरी जनता का"],"अब पाठ का सार दोहरा लीजिए। आंग सान सू की को उन्नीस सौ इक्यानवे में नोबेल शांति पुरस्कार मिला। उस समय वे म्यांमार में अपने घर में नज़रबंद थीं, इसलिए उनके बेटे ने ओस्लो में पुरस्कार स्वीकार किया और भाषण दिया। भाषण में लोकतंत्र, मानवाधिकार और अहिंसा के महत्व पर ज़ोर है। बेटे ने कहा कि यह पुरस्कार पूरे देश की जनता का है। इस सार को पाँच वाक्यों में अपने शब्दों में लिखकर देखिए।"),
C("❓","संभावित परीक्षा प्रश्न",["भाषण किसने दिया और क्यों","पुरस्कार किसका है","सू की ने कौन सा रास्ता चुना","पाठ का संदेश"],"परीक्षा के प्रश्न देखिए। पहला, भाषण किसने दिया और क्यों? उत्तर, सू की के बेटे ने, क्योंकि वे नज़रबंद थीं और ओस्लो नहीं आ सकती थीं। दूसरा, पुरस्कार किसका है? उत्तर, पूरी बर्मी जनता का। तीसरा, सू की ने कौन सा रास्ता चुना? उत्तर, अहिंसा का, जैसे गांधी जी ने। चौथा, संदेश? उत्तर, अहिंसा में शक्ति है और लोकतंत्र तथा मानवाधिकार हर इंसान का हक़ हैं। उत्तर पूरे वाक्य में और संदर्भ के साथ लिखिए।"),
Q("आपके अनुसार अहिंसा के रास्ते पर चलना आसान है या मुश्किल, और क्यों?","मुश्किल है, क्योंकि इसमें धैर्य, साहस और आत्म-नियंत्रण चाहिए, पर इसका असर लंबे समय तक रहता है।","एक सोचने वाला प्रश्न। आपके अनुसार अहिंसा के रास्ते पर चलना आसान है या मुश्किल, और क्यों? सोचिए। ... यह मुश्किल है, क्योंकि इसमें धैर्य, साहस और आत्म-नियंत्रण चाहिए। पर इसका असर लंबे समय तक रहता है। कारण के साथ अपना उत्तर लिखिए।"),
],7)
